import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix, uniform } from 'three/tsl';

export default function createNode(config, ctx) {
  const { THREE } = ctx;

  // ─────────────────────────────────────────────────────────────
  // 1. BUILD STAGE BACKDROP (if this is the primary render)
  // ─────────────────────────────────────────────────────────────
  const group = new THREE.Group();

  // Interpret config.intent?.visualSpec?.colors or fallback
  const colors = config.colors ?? config.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10'
  };

  // ─────────────────────────────────────────────────────────────
  // 2. LOAD & APPLY TEXTURE
  // ─────────────────────────────────────────────────────────────
  const planeGeometry = new THREE.PlaneGeometry(2, 1.25);

  // Create material with texture loading
  const planeMaterial = new MeshBasicNodeMaterial({
    color: 0xffffff,
    side: THREE.DoubleSide,
    transparent: true
  });

  const planeMesh = new THREE.Mesh(planeGeometry, planeMaterial);
  group.add(planeMesh);

  // Load texture asynchronously
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((texture) => {
      texture.colorSpace = THREE.SRGBColorSpace;
      planeMaterial.map = texture;
      planeMaterial.needsUpdate = true;
    });
  }

  // ─────────────────────────────────────────────────────────────
  // 3. APPLY SCENE POSITION (adapter will apply this, but store for reference)
  // ─────────────────────────────────────────────────────────────
  if (config.scenePosition) {
    group.position.copy(config.scenePosition);
  } else {
    group.position.set(0, -0.3, 0);
  }

  if (config.sceneRotation) {
    group.rotation.setFromVector3(config.sceneRotation);
  }

  if (config.sceneScale) {
    group.scale.copy(config.sceneScale);
  }

  // ─────────────────────────────────────────────────────────────
  // 4. SETUP CLEANUP
  // ─────────────────────────────────────────────────────────────
  group.userData.cleanup = () => {
    planeGeometry.dispose();
    planeMaterial.dispose();
    if (planeMaterial.map) {
      planeMaterial.map.dispose();
    }
  };

  return group;
}
